    """Return (score, aligned_a, aligned_b)."""
    # Handle empty sequences
    if not seq_a and not seq_b:
        return (0, "", "")
    if not seq_a:
        return (gap_open + (len(seq_b) - 1) * gap_extend, "-" * len(seq_b), seq_b)
    if not seq_b:
        return (gap_open + (len(seq_a) - 1) * gap_extend, seq_a, "-" * len(seq_a))

    # Initialize the DP table
    len_a, len_b = len(seq_a), len(seq_b)
    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]

    # Initialize the first row and column
    for i in range(len_a + 1):
        dp[i][0] = gap_open + (i - 1) * gap_extend
    for j in range(len_b + 1):
        dp[0][j] = gap_open + (j - 1) * gap_extend

    # Fill the DP table
    for i in range(1, len_a + 1):
        for j in range(1, len_b + 1):
            # Calculate the score for matching/mismatch
            if seq_a[i-1] == seq_b[j-1]:
                score = match
            else:
                score = mismatch

            # Calculate the score for gaps
            gap_score = gap_open + (min(i, j) - 1) * gap_extend

            # Choose the maximum score
            dp[i][j] = max(
                dp[i-1][j-1] + score,
                dp[i-1][j] + gap_score,
                dp[i][j-1] + gap_score
            )

    # Trace back to find the optimal alignment
    i, j = len_a, len_b
    aligned_a, aligned_b = "", ""

    while i > 0 and j > 0:
        if seq_a[i-1] == seq_b[j-1]:
            aligned_a = seq_a[i-1] + aligned_a
            aligned_b = seq_b[j-1] + aligned_b
            i -= 1
            j -= 1
        elif dp[i-1][j] + gap_score == dp[i][j]:
            aligned_a = seq_a[i-1] + aligned_a
            aligned_b = "-" + aligned_b
            i -= 1
        else:
            aligned_a = "-" + aligned_a
            aligned_b = seq_b[j-1] + aligned_b
            j -= 1

    # Handle remaining characters
